// Lead Radar: merge all feeds, keep relevant + recent posts, cap volume.
// Weighted skill keywords: 3 = core service, 2 = strong fit, 1 = general full-stack work
const KEYWORDS = {
  'n8n': 3, 'make.com': 3, 'zapier': 3, 'automation': 3, 'automate': 3, 'workflow automation': 3,
  'whatsapp': 3, 'whatsapp bot': 3, 'chatbot': 3, 'chat bot': 3, 'ai chatbot': 3, 'ai agent': 3, 'ai assistant': 3,
  'voice ai': 3, 'voice agent': 3, 'llm': 3, 'rag': 3, 'openai': 3, 'gpt': 3, 'groq': 3,
  'shopify': 3, 'woocommerce': 3, 'e-commerce': 3, 'ecommerce': 3, 'online store': 3,
  'api integration': 2, 'integration': 2, 'integrations': 2, 'webhook': 2, 'twilio': 2, 'crm': 2,
  'stripe': 2, 'payment gateway': 2, 'payment integration': 2, 'supabase': 2,
  'full stack': 2, 'full-stack': 2, 'fullstack': 2, 'next.js': 2, 'nextjs': 2,
  'website': 1, 'web development': 1, 'web developer': 1, 'web app': 1, 'landing page': 1,
  'react': 1, 'node.js': 1, 'nodejs': 1, 'python': 1, 'wordpress': 1, 'api': 1, 'rest api': 1
};
const BLOCK = ['unpaid', 'equity only', 'security clearance', 'us citizens only', 'must be located in the us'];
const MAX_AGE_DAYS = 3;   // ignore posts older than this
const MAX_PER_RUN = 15;   // Groq free tier: 15 posts x 6 runs = 90 calls/day, about half the daily token limit

const strip = (html) => String(html || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ').trim();

const toIso = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const d = typeof v === 'number' ? new Date(v < 1e12 ? v * 1000 : v) : new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
};

// whole-word match, so 'rag' does not match 'storage' or 'average'
const hasWord = (text, k) => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(text);

const safe = (nodeName) => {
  try { return $(nodeName).all().map(i => i.json); } catch (e) { return []; }
};

const out = [];

// 1) Freelancer.com projects (gig work)
for (const r of safe('Fetch Freelancer')) {
  for (const p of (r.result && r.result.projects) || []) {
    const cur = (p.currency && p.currency.code) || '';
    const b = p.budget || {};
    out.push({
      source: 'freelancer',
      external_id: String(p.id),
      title: p.title,
      company: 'Freelancer.com client',
      url: p.seo_url ? 'https://www.freelancer.com/projects/' + p.seo_url : 'https://www.freelancer.com/projects/' + p.id,
      location: 'Remote (freelance)',
      budget: (b.minimum || b.maximum) ? `${b.minimum || '?'}-${b.maximum || '?'} ${cur}${p.type === 'hourly' ? '/hr' : ''}` : '',
      description: strip(p.description || p.preview_description),
      posted_at: toIso(p.time_submitted),
    });
  }
}

// 2) Remotive
for (const r of safe('Fetch Remotive')) {
  for (const j of r.jobs || []) {
    out.push({
      source: 'remotive',
      external_id: String(j.id),
      title: j.title,
      company: j.company_name,
      url: j.url,
      location: j.candidate_required_location || '',
      budget: j.salary || '',
      description: strip(j.description),
      posted_at: toIso(j.publication_date),
    });
  }
}

// 3) RemoteOK (first array element is a legal notice, skipped by the id check)
for (const j of safe('Fetch RemoteOK')) {
  if (!j.id || !j.position) continue;
  out.push({
    source: 'remoteok',
    external_id: String(j.id),
    title: j.position,
    company: j.company,
    url: j.url || ('https://remoteok.com/remote-jobs/' + j.id),
    location: j.location || '',
    budget: (j.salary_min || j.salary_max) ? `${j.salary_min || '?'}-${j.salary_max || '?'} USD/yr` : '',
    description: strip(j.description) + (Array.isArray(j.tags) ? ' Tags: ' + j.tags.join(', ') : ''),
    posted_at: toIso(j.date || j.epoch),
  });
}

// 4) Jobicy
for (const r of safe('Fetch Jobicy')) {
  for (const j of r.jobs || []) {
    out.push({
      source: 'jobicy',
      external_id: String(j.id),
      title: j.jobTitle,
      company: j.companyName,
      url: j.url,
      location: j.jobGeo || '',
      budget: (j.salaryMin || j.salaryMax) ? `${j.salaryMin || '?'}-${j.salaryMax || '?'} ${j.salaryCurrency || ''}${j.salaryPeriod ? '/' + j.salaryPeriod : ''}` : '',
      description: strip(j.jobDescription || j.jobExcerpt),
      posted_at: toIso(j.pubDate),
    });
  }
}

// 5) Himalayas (search API)
for (const r of safe('Fetch Himalayas')) {
  for (const j of r.jobs || []) {
    const link = (typeof j.guid === 'string' && j.guid.startsWith('http')) ? j.guid : j.applicationLink;
    out.push({
      source: 'himalayas',
      external_id: String(j.guid || link),
      title: j.title,
      company: j.companyName,
      url: link,
      location: Array.isArray(j.locationRestrictions) && j.locationRestrictions.length ? j.locationRestrictions.join(', ') : 'Worldwide',
      budget: (j.minSalary || j.maxSalary) ? `${j.minSalary || '?'}-${j.maxSalary || '?'} ${j.currency || ''}${j.salaryPeriod ? '/' + j.salaryPeriod : ''}` : '',
      description: strip(j.description || j.excerpt),
      posted_at: toIso(j.pubDate),
    });
  }
}

// 6) Working Nomads (returns a plain array of jobs)
for (const j of safe('Fetch Working Nomads')) {
  if (!j.url || !j.title) continue;
  out.push({
    source: 'workingnomads',
    external_id: String(j.url),
    title: j.title,
    company: j.company_name,
    url: j.url,
    location: j.location || '',
    budget: '',
    description: strip(j.description) + (j.tags ? ' Tags: ' + j.tags : ''),
    posted_at: toIso(j.pub_date),
  });
}

// 7) Arbeitnow (remote jobs only)
for (const r of safe('Fetch Arbeitnow')) {
  for (const j of r.data || []) {
    if (!j.remote) continue;
    out.push({
      source: 'arbeitnow',
      external_id: String(j.slug || j.url),
      title: j.title,
      company: j.company_name,
      url: j.url,
      location: j.location || 'Remote',
      budget: '',
      description: strip(j.description) + (Array.isArray(j.tags) ? ' Tags: ' + j.tags.join(', ') : ''),
      posted_at: toIso(j.created_at),
    });
  }
}

// 8) Hacker News: comments in the monthly "Who is hiring" / "Seeking freelancer" threads
for (const r of safe('Fetch Hacker News')) {
  for (const h of r.hits || []) {
    const story = String(h.story_title || '').toLowerCase();
    if (!story.includes('hiring') && !story.includes('freelancer')) continue;
    const text = strip(h.comment_text);
    if (!text) continue;
    out.push({
      source: 'hackernews',
      external_id: String(h.objectID),
      title: text.slice(0, 120),
      company: text.split('|')[0].slice(0, 80),
      url: 'https://news.ycombinator.com/item?id=' + h.objectID,
      location: '',
      budget: '',
      description: text + ' (Thread: ' + h.story_title + ')',
      posted_at: toIso(h.created_at),
    });
  }
}

// 9) We Work Remotely (RSS)
for (const j of safe('Read We Work Remotely')) {
  if (!j.link || !j.title) continue;
  const parts = String(j.title).split(':');
  out.push({
    source: 'weworkremotely',
    external_id: String(j.guid || j.link),
    title: parts.length > 1 ? parts.slice(1).join(':').trim() : j.title,
    company: parts.length > 1 ? parts[0].trim() : '',
    url: j.link,
    location: j.region || '',
    budget: '',
    description: strip(j.content || j.contentSnippet || j.description),
    posted_at: toIso(j.isoDate || j.pubDate),
  });
}

// 10) Reddit r/forhire (RSS) — only [Hiring] posts
for (const j of safe('Read Reddit ForHire')) {
  if (!j.link || !j.title || !/\[hiring\]/i.test(j.title)) continue;
  out.push({
    source: 'reddit_forhire',
    external_id: String(j.id || j.guid || j.link),
    title: String(j.title).replace(/\[hiring\]/i, '').trim(),
    company: 'Reddit r/forhire',
    url: j.link,
    location: '',
    budget: '',
    description: strip(j.content || j.contentSnippet),
    posted_at: toIso(j.isoDate || j.pubDate),
  });
}

const cutoff = Date.now() - MAX_AGE_DAYS * 24 * 60 * 60 * 1000;
const seen = new Set();
const leads = out
  .filter(l => l.external_id && l.title && l.url)
  .map(l => {
    const text = (l.title + ' ' + l.description).toLowerCase();
    const title = String(l.title).toLowerCase();
    let kw = 0;
    for (const [k, w] of Object.entries(KEYWORDS)) {
      if (hasWord(text, k)) kw += w;
      if (hasWord(title, k)) kw += w;          // matches in the title count double
    }
    return { ...l, kw, blocked: BLOCK.some(k => text.includes(k)) };
  })
  .filter(l => l.kw >= 3 && !l.blocked)       // at least one core skill, or several general ones
  .filter(l => !l.posted_at || new Date(l.posted_at).getTime() >= cutoff)
  .filter(l => { const k = l.source + ':' + l.external_id; if (seen.has(k)) return false; seen.add(k); return true; })
  .sort((a, b) => (b.kw - a.kw) || String(b.posted_at).localeCompare(String(a.posted_at)))   // best skill match first
  .slice(0, MAX_PER_RUN)                         // the rest wait for the next run (they are not saved yet)
  .map(({ kw, blocked, ...l }) => ({ ...l, description: l.description.slice(0, 1000) }));   // shorter text = fewer Groq tokens

if (leads.length === 0) return [];
// One item carrying all leads as JSON -> a single INSERT ... ON CONFLICT DO NOTHING
return [{ json: { count: leads.length, payload: JSON.stringify(leads) } }];

// Pair each Groq answer with the lead it scored, and parse the JSON safely.
const leads = $('Only New Leads').all();
return $input.all().map((item, i) => {
  const lead = (leads[i] && leads[i].json) || {};
  let r = { score: 0, fit: 'poor', reason: 'Scoring failed', suggested_pitch: '' };
  try {
    const content = item.json.choices[0].message.content;
    const match = String(content).match(/\{[\s\S]*\}/);
    r = { ...r, ...JSON.parse(match ? match[0] : content) };
  } catch (e) {
    r.reason = 'Scoring failed: ' + (item.json.error ? JSON.stringify(item.json.error).slice(0, 150) : e.message);
  }
  const score = Math.max(0, Math.min(100, parseInt(r.score, 10) || 0));
  return {
    json: {
      id: lead.id,
      source: lead.source,
      title: lead.title,
      company: lead.company,
      url: lead.url,
      budget: lead.budget,
      location: lead.location,
      score,
      fit: String(r.fit || '').slice(0, 20),
      reason: String(r.reason || '').slice(0, 500),
      suggested_pitch: String(r.suggested_pitch || '').slice(0, 800),
    }
  };
});

// Keep only hot leads (score >= 80) and build the alert text.
const HOT = 80;
return $('Parse Score').all()
  .filter(i => i.json.score >= HOT)
  .map(i => {
    const l = i.json;
    const content = [
      `🔥 **Hot lead (${l.score}/100)**: ${l.title}`,
      `🏢 ${l.company || 'Unknown'} · 🌍 ${l.location || 'n/a'} · 💰 ${l.budget || 'n/a'} · 📡 ${l.source}`,
      `✅ ${l.reason}`,
      `💬 Pitch idea: ${l.suggested_pitch}`,
      `🔗 ${l.url}`,
    ].join('\n').slice(0, 1900);
    return { json: { ...l, content } };
  });
